    "rationale": "候选主定理完整构造耦合概率测度，并从密度假设推导正规化、边缘、对角与非对角质量以及全变差等式；两个退化端点均在证明中显式处理。中性技术事实同时确认构建、逃逸扫描和公理审计通过。"
  },
  "statement_fidelity": {
    "status": "通过",
    "assessment": "公开主定理 prob_8_7 对实数上的两个共同由勒贝格测度支配的概率密度进行表述，结论给出联合概率测度、两个指定边缘以及相等和不等事件的精确概率。它与教材的连续型最大耦合陈述及任务合同一致。",
    "strength": "候选以可测、可积、逐点非负且积分为 1 明确展开概率密度所需条件；这比仅写分段连续更直接，并未削弱最大耦合结论。任务允许采用等价的耦合测度，所以未显式建立四个辅助随机变量的概率空间不构成缺失。",
    "conclusion_match": "不等概率被证明等于 totalVariationDistance，相等概率被证明等于 1 减去该距离，且两个边缘分别等于由 f、g 生成的密度测度。"
  },
  "obligation_closure": {
    "status": "闭合",
    "obligations": [
      {
        "obligation": "构造公共部分和两个剩余部分",
        "status": "完成",
        "evidence": "定义 C=min(f,g)、L=f-C、R=g-C，并令 MC、ML、MR 为相应密度测度。"
      },
      {
        "obligation": "正规化三个部分",
        "status": "完成",
        "evidence": "prob87NormalizeAt 在质量非零时按质量倒数缩放，在质量为零时选用狄拉克概率测度；prob87NormalizeAt_isProbability 和 prob87_smul_normalizeAt 分别证明概率性及缩放还原。"
      },
      {
        "obligation": "处理公共质量为 0 或 1 的端点",
        "status": "完成",
        "evidence": "正规化定义对零质量分支使用狄拉克测度；残余对角质量证明对 p=0 单独分支处理。q+p=1 因而同时覆盖 q=0、q=1。"
      },
      {
        "obligation": "证明所得对象是概率测度",
        "status": "完成",
        "evidence": "prob87_measure_core 由 q+p=1、各正规化测度质量为 1 推出混合测度总质量为 1。"
      },
      {
        "obligation": "证明两个边缘正确",
        "status": "完成",
        "evidence": "证明公共对角测度的两个投影均为 U，乘积残余的投影分别为 V、W，再用密度分解及正规化还原得到目标边缘。"
      },
      {
        "obligation": "证明相等与不等事件概率达到全变差界",
        "status": "完成",
        "evidence": "公共分支完全位于对角线上，残余乘积分支的对角质量为零；随后利用连续密度全变差公式证明 p 等于全变差距离，得到对角质量 1-p 和非对角质量 p。"
      }
    ]
  },
  "proof_route_assessment": {
    "status": "有效",
    "route": "先将两密度分解为共同最小值部分及左右剩余部分，再分别正规化。最终耦合是权重 q 的公共对角测度与权重 p 的剩余乘积测度之和。",
    "maximality_argument": "支持文件中的连续密度全变差公式把剩余质量识别为二分之一绝对密度差积分，即全变差距离；候选据此证明不等事件恰有该质量。",
    "independence_equivalence": "剩余分支采用 V.prod W，落实了该分支中两次抽样的独立性；公共分支采用 x 映到 (x,x) 的像测度。该测度级实现符合合同允许的等价路线。",
    "escape_assessment": "未发现 sorry、admit、新增公理、私有不透明结论替代证明或仅凭构建结果断言语义成立的情形。"
  },
  "public_premise_check": {
    "status": "通过",
    "target_premises": [
      "f、g 可测",
      "f、g 对勒贝格测度可积",
      "f、g 逐点非负",
      "f、g 的积分均为 1"
